CREATE TABLE IF NOT EXISTS player_statistics (
  id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  player_id INTEGER,
  player_name TEXT,
  first_name TEXT,
  last_name TEXT,
  age INTEGER,
  birth_date TEXT,
  birth_place TEXT,
  birth_country TEXT,
  nationality TEXT,
  height_cm INTEGER,
  weight_kg INTEGER,
  injured INTEGER,
  photo_url TEXT,
  team_id INTEGER,
  team_name TEXT,
  team_logo_url TEXT,
  league_id INTEGER,
  league_name TEXT,
  league_country TEXT,
  league_logo_url TEXT,
  league_flag_url TEXT,
  league_season INTEGER,
  appearances INTEGER,
  lineups INTEGER,
  minutes INTEGER,
  shirt_number INTEGER,
  position TEXT,
  rating REAL,
  captain INTEGER,
  substitutes_in INTEGER,
  substitutes_out INTEGER,
  substitutes_bench INTEGER,
  shots_total INTEGER,
  shots_on INTEGER,
  goals_total INTEGER,
  goals_conceded INTEGER,
  goals_assists INTEGER,
  goals_saves INTEGER,
  passes_total INTEGER,
  passes_key INTEGER,
  passes_accuracy REAL,
  tackles_total INTEGER,
  tackles_blocks INTEGER,
  tackles_interceptions INTEGER,
  duels_total INTEGER,
  duels_won INTEGER,
  dribbles_attempts INTEGER,
  dribbles_success INTEGER,
  dribbles_past INTEGER,
  fouls_drawn INTEGER,
  fouls_committed INTEGER,
  cards_yellow INTEGER,
  cards_yellow_red INTEGER,
  cards_red INTEGER,
  penalty_won INTEGER,
  penalty_committed INTEGER,
  penalty_scored INTEGER,
  penalty_missed INTEGER,
  penalty_saved INTEGER,
  source_file TEXT NOT NULL,
  source_row INTEGER NOT NULL,
  imported_at TEXT NOT NULL,
  UNIQUE(player_id, team_id, league_id, league_season)
);
CREATE INDEX IF NOT EXISTS player_statistics_player_idx ON player_statistics(player_id);
CREATE INDEX IF NOT EXISTS player_statistics_team_idx ON player_statistics(team_id, league_season);
CREATE INDEX IF NOT EXISTS player_statistics_league_idx ON player_statistics(league_id, league_season);

